#!/usr/bin/env bash
# @generated by @metaobjectsdev/pack-cloudflare (cloudflare-deploy) — hand edits are kept by a three-way merge on regeneration; meta verify --codegen checks only the generated parts.
# Deploys app.service acme::quiz::Quiz.site to one environment, from the model:
#   1. copies its secrets from the vault (deploy/cloudflare/sync-secrets.sh, skipped with --no-secrets),
#   2. runs `wrangler deploy` with the environment's block of wrangler.jsonc.
# Build-time settings are read by the build from this machine's environment; the values the model gives
# are exported first, and a value already in the environment wins.
#
# Needs: what deploy/cloudflare/wrangler.sh needs.
#
#   bash deploy/cloudflare/deploy.sh <environment> [--no-secrets]
set -euo pipefail
cd "$(dirname "$0")/../.."

ENVIRONMENT="${1:-}"
SECRETS=1
for arg in "${@:2}"; do
  case "$arg" in
    --no-secrets) SECRETS=0 ;;
    *) echo 'usage: bash deploy/cloudflare/deploy.sh <environment> [--no-secrets]' >&2; exit 2 ;;
  esac
done
case "$ENVIRONMENT" in production|staging) ;; *) echo 'usage: bash deploy/cloudflare/deploy.sh <environment> [--no-secrets] (environments: production, staging)' >&2; exit 2 ;; esac

if [ "$SECRETS" = 1 ]; then bash deploy/cloudflare/sync-secrets.sh "$ENVIRONMENT"; fi

case "$ENVIRONMENT" in
  production)
    bash deploy/cloudflare/wrangler.sh "$ENVIRONMENT" deploy --config wrangler.jsonc
    ;;
  staging)
    bash deploy/cloudflare/wrangler.sh "$ENVIRONMENT" deploy --config wrangler.jsonc --env staging
    ;;
  *) echo 'usage: bash deploy/cloudflare/deploy.sh <environment> [--no-secrets] (environments: production, staging)' >&2; exit 2 ;;
esac
